<?php defined('BASEPATH') OR exit('No direct script access allowed');class Crm extends MY_Controller{private $c;function __construct(){parent::__construct();$this->c=$this->require_auth();if(!$this->c)return;$this->load->model('Crm_model','crm');}function resource($type,$id=NULL){if(!in_array($type,array('contacts','companies','deals','activities'),TRUE))return $this->fail('NOT_FOUND','Resource not found',404);$m=$this->input->method(TRUE);if($m==='GET'){if($id){$r=$this->crm->one($type,$id,$this->c['organizationId']);return $r?$this->respond($r):$this->fail('NOT_FOUND','Record not found',404);}$filters=array();foreach(array('status','stage','companyId','contactId','dealId','kind') as $f)if($this->input->get($f)!==NULL){$parts=preg_split('/(?=[A-Z])/',$f);$filters[strtolower(implode('_',$parts))]=$this->input->get($f);}if($this->input->get('open')==='true'&&$type==='deals'){$rows=$this->crm->list_resource($type,$this->c['organizationId'],$filters);return $this->respond(array_values(array_filter($rows,function($r){return!in_array($r['stage'],array('closed_won','closed_lost'),TRUE);})));}$rows=$this->crm->list_resource($type,$this->c['organizationId'],$filters);$q=mb_strtolower(trim((string)$this->input->get('q')));if($q)$rows=array_values(array_filter($rows,function($r)use($q){return strpos(mb_strtolower(json_encode($r)),$q)!==FALSE;}));return $this->respond($rows);}if($m==='DELETE')return $this->crm->remove($type,$id,$this->c['organizationId'])?$this->respond(array('deleted'=>TRUE,'id'=>$id)):$this->fail('NOT_FOUND','Record not found',404);$d=$this->body();$required=array('contacts'=>array('firstName','lastName'),'companies'=>array('name'),'deals'=>array('name','companyId','amountCents'),'activities'=>array('kind','subject'));if(!$id)foreach($required[$type] as $f)if(!isset($d[$f])||$d[$f]==='')return $this->fail('VALIDATION_ERROR',$f.' required',422);if(isset($d['companyId'])&&$d['companyId']&&!$this->crm->one('companies',$d['companyId'],$this->c['organizationId']))return $this->fail('VALIDATION_ERROR','Company not found in organization',422);if(isset($d['contactId'])&&$d['contactId']&&!$this->crm->one('contacts',$d['contactId'],$this->c['organizationId']))return $this->fail('VALIDATION_ERROR','Contact not found in organization',422);if(isset($d['dealId'])&&$d['dealId']&&!$this->crm->one('deals',$d['dealId'],$this->c['organizationId']))return $this->fail('VALIDATION_ERROR','Deal not found in organization',422);$r=$this->crm->save($type,$id,$this->c['organizationId'],$this->c['sub'],$d);return $r?$this->respond($r,$id?200:201):$this->fail('NOT_FOUND','Record not found',404);}function stages(){return $this->respond($this->crm->stages());}function dashboard(){return $this->respond($this->crm->rollup($this->c['organizationId']));}}
